let state;try{state=JSON.parse(localStorage.getItem(key))||seed();}catch{state=seed();}state.pizzaPrices??={...D.defaultPizzaPrices};state.products.filter(p=>p.kind==='pizza').forEach(p=>p.surcharge??=0);if(state.version!==2){for(const [id,name,surcharge]of [['p6','Atum',500],['p7','Picanha com alho',1000]])if(!state.products.some(p=>p.name.toLowerCase()===name.toLowerCase()))state.products.push({id,name,surcharge,kind:'pizza',available:true,negative:false,unit:'pizza'});state.version=2;}let branch='f1',page='dashboard',filter='',registerTab='products',registerSearch='',registerKind='',registerAvailability='',productionSector='todos',draft=[];
