function audit(action,detail){state.audit.unshift({at:Date.now(),branch,action,detail});}
function toast(t){if($('#modal').open&&$('#modal-message')){const message=$('#modal-message');message.textContent=t;message.hidden=false;message.scrollIntoView?.({block:'nearest',behavior:'smooth'});return;}$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function badge(text,color=''){return `<span class="badge ${color}">${esc(text)}</span>`;}
function statusBadge(s){return badge(s,({'pendente':'orange','aberta':'blue','fechada':'green','cancelada':'red','aguardando':'orange','em preparo':'blue','pronto':'green','entregue':'green'})[s]||'');}
function btn(label,action,id='',cls='secondary small'){return `<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;}
function title(name,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${esc(state.branches.find(b=>b.id===branch).name)}</div><h1>${name}</h1><div class="sub">${sub}</div></div>${action}</div>`;}
function locationLabel(o){return o.type==='mesa'?`Mesa ${o.tables.join(' + ')}`:o.type==='delivery'?`Delivery #${o.number}`:`Retirada #${o.number}`;}
