const nav=[['dashboard','◫','Visão geral'],['tables','▦','Mesas e comandas'],['orders','☷','Pedidos'],['production','◷','Produção e balcão'],['registers','◇','Cadastros'],['stock','▤','Estoque'],['requests','◇','Solicitações de compra'],['purchases','↙','Compras e entradas'],['cash','＄','Caixa e financeiro'],['history','≡','Histórico']];
$('#nav').innerHTML=nav.map(([id,icon,name])=>`<button data-page="${id}"><span class="ico">${icon}</span>${name}</button>`).join('');$('#branch').innerHTML=state.branches.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('');
$('#branch').onchange=e=>{branch=e.target.value;filter='';render();};$('#reset').onclick=()=>modal('Restaurar demonstração','<p>Isso apaga as alterações demonstrativas deste navegador e recria os cenários das três filiais.</p>',btn('Voltar','close')+btn('Restaurar dados fictícios','reset-confirm','','danger'));
