function ordersView(){let os=orders().filter(o=>!filter||`${o.number} ${locationLabel(o)} ${o.customer} ${o.status}`.toLowerCase().includes(filter.toLowerCase()));return title('Pedidos','Mesa, retirada e delivery manual.',btn('+ Novo pedido','new-order','','primary'))+`<div class="toolbar"><input id="search" placeholder="Buscar número, mesa, cliente ou situação" value="${esc(filter)}" aria-label="Buscar pedidos"></div><section class="panel table-scroll"><table><thead><tr><th>Pedido</th><th>Destino</th><th>Situação</th><th>Total</th><th>Saldo</th><th></th></tr></thead><tbody>${os.sort((a,b)=>b.created-a.created).map(o=>`<tr><td><b>#${o.number}</b><small>${new Date(o.created).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></td><td>${locationLabel(o)}<small>${esc(o.customer||'Atendimento de mesa')}</small></td><td>${statusBadge(o.status)}</td><td>${money(D.total(o))}</td><td>${money(remaining(o))}</td><td>${btn('Abrir','order-detail',o.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum pedido encontrado.</td></tr>'}</tbody></table></section>`;}
function production(){const tickets=orders().filter(o=>o.status==='aberta').flatMap(o=>o.items.filter(i=>!i.cancelled&&i.status!=='entregue'&&(productionSector==='todos'||i.sector===productionSector)).map(i=>({o,i})));const stages=['aguardando','em preparo','pronto'];return title('Produção e balcão','O prazo começa no pedido confirmado pelo garçom. O balcão confirma a entrega.',btn('Prazo e atendimento','operation-settings','','secondary'))+`<div class="toolbar"><div class="tabs">${[['todos','Todos'],['cozinha','Cozinha'],['bar','Bar']].map(([k,t])=>btn(t,'sector',k,k===productionSector?'selected':'')).join('')}</div><span class="sub">Prazo: ${unit().settings.deadline} min • alerta nos últimos 15 min</span></div><div class="board">${stages.map(stage=>`<section class="board-col"><h3>${stage==='pronto'?'Pronto • balcão':stage} ${badge(tickets.filter(t=>t.i.status===stage).length)}</h3>${tickets.filter(t=>t.i.status===stage).map(({o,i})=>{const elapsed=Math.max(0,Math.floor((Date.now()-o.confirmed)/60000)),left=unit().settings.deadline-elapsed;return `<article class="ticket"><div class="row"><b>${locationLabel(o)}</b>${badge(i.sector,i.sector==='bar'?'blue':'')}</div><p>${i.qty}× ${esc(i.name)}</p><p class="sub">${esc(i.description)}</p>${i.notes?`<p class="sub accent">Obs.: ${esc(i.notes)}</p>`:''}<div class="time">#${o.number} • ${elapsed} min decorridos</div>${badge(left<0?`Atraso de ${-left} min`:`${left} min restantes`,left<=15?'red':'green')}${btn(stage==='aguardando'?'Iniciar preparo':stage==='em preparo'?'Marcar pronto':'Confirmar entrega • balcão','advance',`${o.id}|${i.id}`,'primary small')}</article>`;}).join('')||'<div class="empty">Nenhum item.</div>'}</section>`).join('')}</div>`;}
function registers(){let body='';if(registerTab==='products')body=`<table><thead><tr><th>Produto</th><th>Tipo</th><th>Acréscimo / G / unitário</th><th>Disponibilidade</th><th></th></tr></thead><tbody>${state.products.filter(matchesRegister).map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.unit)}${p.negative?' • permite negativo':''}</small></td><td>${p.kind}</td><td>${p.kind==='pizza'?(p.surcharge?'+'+money(p.surcharge):'Padrão por tamanho'):money(p.prices?.G||p.price||0)}</td><td>${badge(p.available?'Disponível':'Indisponível',p.available?'green':'red')}</td><td><div class="actions">${btn('Editar','product-edit',p.id)}${btn(p.available?'Pausar':'Ativar','product-toggle',p.id)}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum produto encontrado para estes filtros.</td></tr>'}</tbody></table>`;else if(registerTab==='customers')body=listRegister(state.customers,'customer','Cliente','Telefone');else if(registerTab==='suppliers')body=listRegister(state.suppliers,'supplier','Fornecedor','Telefone');else body=`<div class="notice">Os perfis abaixo são cadastros demonstrativos. Não há autenticação ou controle real de acesso nesta etapa.</div>${listRegister(state.users,'user','Nome','Perfil')}`;const types={products:'product',customers:'customer',suppliers:'supplier',users:'user'};return title('Cadastros','Cardápio, produtos, clientes, fornecedores e equipe.',btn('+ Novo cadastro',types[registerTab]+'-edit','','primary'))+`<div class="toolbar"><div class="tabs">${[['products','Produtos e cardápio'],['customers','Clientes'],['suppliers','Fornecedores'],['users','Equipe']].map(([k,t])=>btn(t,'register-tab',k,k===registerTab?'selected':'')).join('')}</div></div>${registerTab==='products'?`<section class="panel"><div class="panel-head"><div><h2>Preços padrão de pizza</h2><p class="sub">Comuns a todos os sabores • maior acréscimo entre os sabores especiais</p></div>${btn('Editar valores','pizza-prices')}</div><div class="mini-grid">${Object.entries(state.pizzaPrices).map(([size,value])=>stat(esc(size),money(value),'Base por pizza')).join('')}</div></section>`:''}${registerFilterBar()}<section class="panel table-scroll">${body}</section>`;}
function listRegister(arr,type,a,b){return `<table><thead><tr><th>${a}</th><th>${b}</th><th></th></tr></thead><tbody>${arr.filter(matchesRegister).map(r=>`<tr><td><b>${esc(r.name)}</b><small>${esc(r.address||'')}</small></td><td>${esc(r.role||r.phone||'—')}</td><td>${btn('Editar',type+'-edit',r.id)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Nenhum cadastro encontrado para esta pesquisa.</td></tr>'}</tbody></table>`;}
function stockView(){const ps=state.products.filter(p=>['bebida','insumo'].includes(p.kind));return title('Estoque','Bebidas por unidade. Despensa por embalagem inteira.',btn('Gerar solicitações por mínimo','auto-purchases','','primary'))+`<div class="notice">Pizza não gera baixa de ingredientes. Sabores têm disponibilidade manual. O saldo pertence à filial selecionada.</div><section class="panel table-scroll"><table><thead><tr><th>Produto / apresentação</th><th>Saldo</th><th>Mínimo</th><th>Regra</th><th>Situação</th><th></th></tr></thead><tbody>${ps.map(p=>{const s=unit().stock[p.id]||0,m=unit().minimum[p.id]||0;return `<tr><td><b>${esc(p.name)}</b><small>${p.kind==='insumo'?'Baixa manual por embalagem':'Baixa ao confirmar pedido'}</small></td><td><b>${s} ${esc(p.unit)}</b></td><td>${m}</td><td>${p.negative?'Permite negativo':'Bloqueia negativo'}</td><td>${badge(s<m?'Abaixo do mínimo':'Regular',s<m?'orange':'green')}</td><td><div class="actions">${btn('Movimentar','stock-move',p.id)}${btn('Mínimo','stock-min',p.id)}${btn('Comprar','purchase-new',p.id)}</div></td></tr>`;}).join('')}</tbody></table></section>`;}
function purchaseView(){return title('Compras e entradas','Área do responsável por compras: atender solicitações e receber mercadorias.',btn('+ Entrada sem solicitação','entry-new','','primary'))+buyerInbox()+`<section class="panel table-scroll"><table><thead><tr><th>Produto</th><th>Solicitado / recebido</th><th>Necessidade</th><th>Situação</th><th></th></tr></thead><tbody>${state.purchases.filter(p=>p.branch===branch&&p.status!=='pendente').map(p=>`<tr><td><b>${esc(product(p.product)?.name)}</b><small>${esc(p.supplier||'Fornecedor a definir')} • ${esc(p.reason)}</small></td><td>${p.qty} / ${p.received||0} ${esc(product(p.product)?.unit)}</td><td>${esc(p.date||'Não informada')}</td><td>${badge(p.status,p.status==='recebida'?'green':'orange')}</td><td><div class="actions">${p.status==='pendente'?btn('Aprovar','purchase-approve',p.id):''}${p.status==='aprovada'?btn('Compra realizada','purchase-bought',p.id):''}${['compra realizada','parcial'].includes(p.status)?btn('Receber','purchase-receive',p.id):''}${!['recebida','cancelada'].includes(p.status)?btn('Cancelar','purchase-cancel',p.id,'danger small'):''}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhuma compra em andamento. Atenda uma solicitação ou registre uma entrada sem solicitação.</td></tr>'}</tbody></table></section><div class="notice">Conferência manual demonstrativa: nota, filial e conversão de embalagem. Leitura de XML e contas a pagar automáticas ficam para a evolução do sistema.</div>`;}
