function cashView(){const os=orders().filter(o=>o.status==='aberta'),cash=unit().cash,ps=orders().flatMap(o=>o.payments.map(p=>({...p,number:o.number,order:o})));return title('Caixa e financeiro','Recebimentos, fechamento de comandas e despesas manuais.',btn(cash.open?'Fechar caixa':'Abrir caixa','cash-toggle','','primary'))+`<div class="stats">${stat('Caixa',cash.open?'Aberto':'Fechado','Operador demonstrativo')}${stat('Dinheiro previsto',money(cashBalance()),'Fundo inicial + dinheiro + movimentos do turno')}${stat('Recebimentos do cenário',money(ps.reduce((s,p)=>s+p.amount,0)),'Dinheiro, Pix e cartão registrados')}${stat('A receber',money(os.reduce((s,o)=>s+remaining(o),0)),'Comandas abertas')}</div><div class="grid-even"><section class="panel"><div class="panel-head"><h2>Comandas para receber</h2>${badge(os.length)}</div>${os.map(o=>`<div class="row"><div><b>${locationLabel(o)}</b><small>#${o.number} • total ${money(D.total(o))}</small></div>${btn(money(remaining(o))+' →','payment',o.id)}</div>`).join('')||'<div class="empty">Nenhuma comanda aberta.</div>'}</section><section class="panel"><div class="panel-head"><h2>Movimentos e despesas</h2><div class="actions">${btn('Sangria / suprimento','cash-move')}${btn('+ Despesa','expense-new')}</div></div>${cash.movements.map(m=>`<div class="row"><div><b>${esc(m.reason)}</b><small>Movimento do caixa</small></div><b>${money(m.amount)}</b></div>`).join('')}${state.expenses.filter(e=>e.branch===branch).map(e=>`<div class="row"><div><b>${esc(e.name)}</b><small>Vence ${esc(e.date)} • ${e.paid?'paga':'pendente'}</small></div><div>${money(e.amount)} ${!e.paid?btn('Pagar','expense-pay',e.id):''}</div></div>`).join('')||'<p class="sub">Cadastre despesas para acompanhar os vencimentos.</p>'}</section></div><section class="panel table-scroll"><h2>Recebimentos registrados</h2><table><thead><tr><th>Comanda / mesa</th><th>Primeiro pedido</th><th>Solicitou fechamento</th><th>Permanência</th><th>Recebimento</th><th>Meio</th><th>Valor</th></tr></thead><tbody>${ps.map(p=>`<tr><td><b>#${p.number}</b><small>${p.order.type==='mesa'?'Mesa '+(p.order.closingTables||p.order.tables).join(' + '):locationLabel(p.order)}</small></td><td>${logTime(p.order.created)}</td><td>${p.order.closingRequested?logTime(p.order.closingRequested):'Não registrado'}</td><td>${stayTime(p.order)}</td><td>${logTime(p.at)}</td><td>${esc(p.method)}</td><td>${money(p.amount)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhum pagamento registrado.</td></tr>'}</tbody></table></section><div class="notice">Registrar Pix ou cartão não comprova recebimento bancário. Conciliação, taxas de cartão e projeções detalhadas serão implementadas posteriormente.</div>`;}
function history(){return title('Histórico da operação','Registro demonstrativo das ações realizadas neste navegador.')+`<section class="panel table-scroll"><table><thead><tr><th>Quando</th><th>Ação</th><th>Detalhes</th></tr></thead><tbody>${state.audit.filter(a=>a.branch===branch).map(a=>`<tr><td>${new Date(a.at).toLocaleString('pt-BR')}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">As ações realizadas aparecerão aqui.</td></tr>'}</tbody></table></section>`;}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,options,value){return `<label>${label}<select name="${name}">${options.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;}
function openNewOrder(table=1,type='mesa'){draft=[];modal('Novo pedido',`<form id="new-order-form"><div class="form-grid">${selectField('Modalidade','type',[['mesa','Mesa'],['retirada','Retirada'],['delivery','Delivery']],type)}${selectField('Mesa inicial','table',unit().tables.filter(t=>!tableOrder(t.id)).map(t=>[t.id,'Mesa '+t.id]),table)}${field('Pessoas na mesa','people',1,'number','min="1" max="100" required')}${selectField('Origem','origin',[['garçom','Garçom • confirmar ao salvar'],['QR demonstrativo','QR • aguarda garçom']],'garçom')}${field('Cliente','customer')}${field('Telefone','phone')}<label class="wide">Endereço de entrega<input name="address" placeholder="Rua, número, bairro e referência"></label>${field('Taxa de entrega (R$)','fee',0,'number','min="0" step="0.01"')}<label>Pagamento externo<select name="external"><option>Pendente</option><option>Informado como pago • conferir no caixa</option></select></label><div class="notice wide" id="service-notice">Taxa de garçom de 10% aplicada automaticamente sobre os itens da mesa.</div></div><hr class="divider"><div class="panel-head"><h3>Itens do pedido</h3>${btn('+ Adicionar item','add-item')}</div><div id="draft-list" class="empty">Adicione uma pizza ou bebida para continuar.</div><div class="total-line"><span id="draft-total-label">Total com taxa de garçom</span><span id="draft-total">R$ 0,00</span></div></form>`,btn('Voltar','close')+btn('Salvar pedido','save-order','','primary'));updateOrderFields();}
function updateOrderFields(){const form=$('#new-order-form');if(!form)return;const type=form.querySelector('[name=type]').value;for(const name of ['table','people','origin','customer','phone','address','fee','external']){const el=form.querySelector('[name="'+name+'"]'),visible=['table','people','origin'].includes(name)?type==='mesa':['address','fee'].includes(name)?type==='delivery':type!=='mesa';el.closest('label').hidden=!visible;el.disabled=!visible;if(['customer','phone','address'].includes(name))el.required=type==='delivery';}$('#service-notice').hidden=type!=='mesa';$('#draft-total-label').textContent=type==='mesa'?'Total com taxa de garçom':'Total do pedido';drawDraft();}
let orderFormCache=null,appendOrderId=null;
function openItem(){if($('#new-order-form'))orderFormCache=new FormData($('#new-order-form'));const flavors=state.products.filter(p=>p.kind==='pizza'&&p.available);modal('Adicionar item',`<form id="item-form"><div class="form-grid">${selectField('Categoria','category',[['pizza','Pizza'],['bebida','Bebida']],'pizza')}${field('Quantidade','qty',1,'number','min="1" max="99" required')}</div><div id="item-builder"></div><label class="field">Observações<textarea name="notes" placeholder="Sem cebola, bem assada…"></textarea></label></form>`,btn('Voltar ao pedido','back-draft')+btn('Adicionar ao pedido','save-item','','primary'));buildItem();}
function buildItem(){const category=$('[name=category]').value;$('#item-builder').innerHTML=category==='pizza'?`<div class="form-grid" style="margin-top:15px">${selectField('Tamanho / modelo','size',Object.keys(D.sizes).map(k=>[k,k]),'G')}</div><label class="pill-check" style="margin-top:15px"><input type="checkbox" name="single-flavor"> Pizza de um sabor só</label><div class="form-grid" id="flavor-parts" style="margin-top:15px"></div><h3 style="margin-top:20px">Borda</h3><label class="pill-check"><input type="checkbox" name="single-border"> Borda de um tipo só</label><div id="border-builder"></div><h3>Adicionais • até 10 opções</h3><p class="sub">Porção padrão por pizza. Marque os adicionais desejados.</p><div class="check-list">${state.products.filter(p=>p.kind==='adicional'&&p.available).map(p=>`<label><input type="checkbox" name="extra" value="${p.id}">${esc(p.name)}</label>`).join('')}</div><div class="summary-box" id="pizza-preview"></div>`:`<div class="form-grid" style="margin:15px 0">${selectField('Produto','drink',state.products.filter(p=>p.kind==='bebida'&&p.available).map(p=>[p.id,p.name+' • '+money(p.price)]))}</div><div class="check-list"><label><input type="checkbox" name="drink-ice"> Copo com gelo</label><label><input type="checkbox" name="drink-lemon"> Copo com gelo e limão</label></div><p class="sub">Opções sem acréscimo. Selecione uma ou deixe ambas desmarcadas.</p>`;if(category==='pizza'){buildBorders();buildParts();}}
function buildParts(){const size=$('[name=size]').value,ps=state.products.filter(p=>p.kind==='pizza'&&p.available),single=$('[name=single-flavor]').checked,previous=[...document.querySelectorAll('#flavor-parts input:checked')].map(el=>el.value),count=single?1:D.sizes[size].parts;$('#flavor-parts').innerHTML=Array.from({length:count},(_,i)=>{const selected=previous[i]||previous[0]||ps[0]?.id;return `<fieldset class="flavor-group"><legend>${single?'Sabor da pizza inteira':'Parte '+(i+1)+' de '+D.sizes[size].parts}</legend><div class="flavor-options">${ps.map(p=>`<label class="flavor-option"><input type="radio" name="flavor-${i}" value="${p.id}" ${selected===p.id?'checked':''} required><span>${esc(p.name)}${p.surcharge?` <small>+${money(p.surcharge)}</small>`:''}</span></label>`).join('')}</div></fieldset>`;}).join('');previewPizza();}
function buildBorders(){const ps=state.products.filter(p=>p.kind==='borda'&&p.available),single=$('[name=single-border]').checked,previous=[...document.querySelectorAll('#border-builder [name=border]')].filter(el=>el.checked).map(el=>el.value).filter(Boolean);$('#border-builder').innerHTML=`<div class="check-list">${single?`<label><input type="radio" name="border" value="" ${!previous.length?'checked':''}>Sem borda</label>`:''}${ps.map((p,index)=>`<label><input type="${single?'radio':'checkbox'}" name="border" value="${p.id}" ${single?previous[0]===p.id?'checked':'':previous.includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div>`;}
function itemData(){const f=new FormData($('#item-form')),qty=Number(f.get('qty'));if(!Number.isInteger(qty)||qty<1||qty>99)throw Error('Quantidade deve ser de 1 a 99.');if(f.get('category')==='bebida'){const p=product(f.get('drink'));if(!p)throw Error('Cadastre uma bebida disponível.');if(f.has('drink-ice')&&f.has('drink-lemon'))throw Error('Selecione apenas uma opção de copo.');return {id:uid(),product:p.id,name:p.name,description:f.has('drink-lemon')?'Copo com gelo e limão':f.has('drink-ice')?'Copo com gelo':'',price:p.price,qty,sector:'bar',notes:f.get('notes'),status:'aguardando',cancelled:false};}const size=f.get('size'),selected=f.has('flavor-0')?Array.from({length:f.has('single-flavor')?1:D.sizes[size].parts},(_,i)=>f.get('flavor-'+i)):f.getAll('flavor'),flavors=f.has('single-flavor')?Array(D.sizes[size].parts).fill(selected[0]):selected,borders=f.getAll('border').filter(Boolean),extras=[...new Set(f.getAll('extra'))].map(id=>({id,qty:1}));return {id:uid(),product:flavors[0],name:'Pizza '+size,description:D.compose(flavors,state.products)+(borders.length?' • '+borders.map(id=>product(id).name).join(' + '):'')+(extras.length?' • Adicionais inclusos: '+extras.map(e=>product(e.id)?.name||e.id).join(', '):''),price:D.pizzaPrice(size,flavors,borders,extras,state.products,state.pizzaPrices),qty,sector:'cozinha',notes:f.get('notes'),status:'aguardando',cancelled:false};}
function previewPizza(){try{const i=itemData();$('#pizza-preview').innerHTML=`<b>${money(i.price)} por pizza</b><div class="recipe">${esc(i.description)}</div>`;}catch(e){$('#pizza-preview').textContent=e.message;}}
function restoreDraft(){if(appendOrderId){orderDetail(appendOrderId);return;}openNewOrderCached();}
function openNewOrderCached(){const oldDraft=draft,cache=orderFormCache;openNewOrder();draft=oldDraft;orderFormCache=cache;if(cache){for(const [k,v]of cache){const el=$(`#new-order-form [name="${k}"]`);if(el)el.value=v;}}updateOrderFields();}
function drawDraft(){if(!$('#draft-list'))return;$('#draft-list').className='';$('#draft-list').innerHTML=draft.map((i,index)=>`<div class="cart-item"><div><b>${i.qty}× ${esc(i.name)}</b><small>${esc(i.description)}</small><small>${esc(i.notes)}</small></div><div>${money(i.price*i.qty)} ${btn('Remover','draft-remove',index,'quiet')}</div></div>`).join('')||'<div class="empty">Adicione itens ao pedido.</div>';const type=$('#new-order-form [name=type]').value,fee=type==='delivery'?D.cents($('#new-order-form [name=fee]').value||0):0;$('#draft-total').textContent=money(D.total({type,items:draft,fee}));}
function confirmOrder(o){if(o.status!=='pendente')return;D.validateStock(o,unit().stock,state.products);o.items.filter(i=>!i.cancelled).forEach(i=>{if(product(i.product)?.kind==='bebida')unit().stock[i.product]=(unit().stock[i.product]||0)-i.qty;});o.confirmed=Date.now();o.status='aberta';audit('Pedido confirmado',`#${o.number} • baixa de bebidas e início do prazo`);}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);if(!o)return;appendOrderId=null;modal(`Comanda #${o.number}`,`<div class="panel-head"><div><b>${locationLabel(o)}</b><p class="sub">${esc(o.customer||'Atendimento de mesa')} ${esc(o.phone||'')}</p>${o.address?`<p>${esc(o.address)}</p>`:''}</div>${statusBadge(o.status)}</div>${o.external?`<p class="sub">Pagamento externo: ${esc(o.external)}</p>`:''}${o.status==='pendente'?'<div class="notice">Solicitação QR demonstrativa aguardando conferência do garçom. Ainda sem baixa de estoque.</div>':''}<div class="actions">${o.type==='mesa'&&['aberta','pendente'].includes(o.status)?btn('Unir / transferir mesas','table-link',o.id):''}${o.status==='aberta'?btn('Adicionar itens','append-item',o.id):''}</div><hr class="divider">${o.items.map(i=>`<div class="cart-item"><div><b>${i.qty}× ${esc(i.name)}</b><small>${esc(i.description)}</small><small>${esc(i.notes)}</small>${statusBadge(i.cancelled?'cancelada':i.status)}</div><div>${money(i.price*i.qty)}${!i.cancelled&&['aberta','pendente'].includes(o.status)?btn('Cancelar','cancel-item',o.id+'|'+i.id,'quiet'):''}</div></div>`).join('')}<div class="summary-box"><div class="row"><span>Subtotal dos itens</span><b>${money(D.subtotal(o))}</b></div>${o.type==='mesa'?`<div class="row"><span>Taxa de garçom • 10%</span><b>${money(D.service(o))}</b></div>`:o.type==='delivery'?`<div class="row"><span>Taxa de entrega</span><b>${money(o.fee)}</b></div>`:''}<div class="row"><span>Desconto</span><b>${money(o.discount)}</b></div><div class="row"><span>Total</span><b>${money(D.total(o))}</b></div><div class="row"><span>Recebido</span><b>${money(D.paid(o))}</b></div><div class="row"><span>Saldo restante</span><b>${money(remaining(o))}</b></div></div>`,btn('Fechar','close')+(o.status==='pendente'?btn('Confirmar • garçom','confirm-order',o.id,'primary'):'')+(o.status==='aberta'?btn('Receber / fechar','payment',o.id,'primary'):'' )+(D.paid(o)>0?btn('Estorno • gerência','refund',o.id,'danger'):''));}
function paymentModal(id){const o=state.orders.find(o=>o.id===id),people=o.people||1;if(o.type==='mesa'&&!o.closingRequested){o.closingRequested=Date.now();o.closingTables=[...o.tables];audit('Fechamento solicitado',`#${o.number} • Mesa ${o.closingTables.join(' + ')} • ${stayTime(o)}`);save();}modal(`Receber • #${o.number}`,`<div class="notice"><b>Para encerrar e liberar a mesa</b><p>1. Informe o valor e clique em <b>Registrar pagamento</b>.<br>2. Confirme a entrega dos itens em Produção e balcão.<br>3. Com saldo zerado e itens entregues, clique em <b>Encerrar comanda</b>.</p><p>${remaining(o)>0?'Saldo a receber: '+money(remaining(o)):'✓ Saldo zerado'} • ${o.items.filter(i=>!i.cancelled&&i.status!=='entregue').length} item(ns) com entrega pendente</p>${o.items.some(i=>!i.cancelled&&i.status!=='entregue')?btn('Abrir produção e balcão','closing-production',id):''}</div><form id="payment-form" data-id="${id}"><div class="mini-grid">${stat('Total',money(D.total(o)),'Comanda')}${stat('Recebido',money(D.paid(o)),'Pagamentos parciais')}${stat('Saldo',money(remaining(o)),'A receber')}</div><p class="sub">${o.type==='mesa'?'Subtotal: '+money(D.subtotal(o))+' • taxa de garçom (10%): '+money(D.service(o)):''}</p><div class="form-grid" style="margin-top:20px">${o.type==='mesa'?selectField('Pagamento externo • conferência no fechamento','external',[['Pendente','Pendente'],['Informado como pago • conferir no caixa','Informado como pago • conferir no caixa']],o.external||'Pendente'):''}${field('Quantidade de pessoas','people',people,'number','min="1" max="100" required')}${field('Desconto fixo (R$) • caixa/gerência','discount',o.discount/100,'number','min="0" step="0.01"')}<div class="wide" id="split-preview"></div>${selectField('Meio de pagamento','method',[['Dinheiro','Dinheiro'],['Pix','Pix'],['Cartão','Cartão']],'Dinheiro')}${field('Valor recebido (R$)','amount',remaining(o)/100,'number','min="0" step="0.01" required')}</div><p class="sub">Em dinheiro, excedente será exibido como troco. Pix e cartão exigem valor até o saldo.</p><div class="notice" style="margin-top:15px">Permissões de caixa/gerência apenas demonstradas nesta fase. Sem autenticação real.</div></form>`,btn('Voltar','order-detail',id)+btn('Registrar pagamento','save-payment',id,'secondary')+btn('Encerrar comanda','close-order',id,'primary'));splitPreview();}
function splitPreview(){const o=state.orders.find(o=>o.id===$('#payment-form').dataset.id);try{const people=Number($('[name=people]').value),discount=D.cents($('[name=discount]').value);if(discount<0||discount>D.total({...o,discount:0})-D.paid(o))throw Error('Desconto ultrapassa o saldo disponível.');const total=D.total({...o,discount}),rem=total-D.paid(o);const describe=values=>{const g={};values.forEach(v=>g[v]=(g[v]||0)+1);return Object.entries(g).map(([v,n])=>`${n} pessoa(s) × ${money(+v)}`).join(' + ');};$('#split-preview').innerHTML=`<div class="summary-box"><b>Divisão em ${people} pessoas</b><p>Total original: ${describe(D.split(total,people))}</p><p>Saldo restante: ${describe(D.split(rem,people))}</p></div>`;}catch(e){$('#split-preview').textContent=e.message;}}
function editProduct(id){const p=product(id)||{name:'',kind:'pizza',unit:'un',available:true,negative:false,price:0,prices:{}};modal(id?'Editar produto':'Novo produto',`<form id="product-form"><div class="form-grid">${field('Nome','name',p.name,'text','required')}${selectField('Tipo','kind',['pizza','bebida','insumo','borda','adicional'].map(k=>[k,k]),p.kind)}${field('Unidade / embalagem','unit',p.unit,'text','required')}${field('Peso/volume da apresentação (opcional)','weight',p.weight||'','number','min="0" step="0.001"')}${field('Acréscimo do sabor especial (R$)','surcharge',(p.surcharge||0)/100,'number','min="0" step="0.01"')}${field('Preço unitário bebida (R$)','price',p.price/100||0,'number','min="0" step="0.01"')}<label class="pill-check"><input type="checkbox" name="negative" ${p.negative?'checked':''}> Permitir saldo negativo</label><div class="wide"><h3>Preços por tamanho • apenas borda ou adicional</h3></div>${Object.keys(D.sizes).map(k=>field(k+' (R$)','size-'+k,(p.prices?.[k]||0)/100,'number','min="0" step="0.01" required')).join('')}</div></form>`,btn('Voltar','close')+btn('Salvar cadastro','product-save',id,'primary'));updateProductFields();}
function editSimple(type,id){const arr=state[{customer:'customers',supplier:'suppliers',user:'users'}[type]],r=arr.find(r=>r.id===id)||{};modal('Cadastro • '+{customer:'cliente',supplier:'fornecedor',user:'equipe'}[type],`<form id="simple-form"><div class="form-grid">${field('Nome','name',r.name,'text','required')}${type==='user'?selectField('Perfil demonstrativo','role',['Dono','Gerência','Compras/estoque','Caixa','Garçom','Cozinha','Bar','Balcão'].map(k=>[k,k]),r.role):field('Telefone','phone',r.phone)}${type==='customer'?field('CPF (usar fictício)','cpf',r.cpf):''}${type==='customer'?`<label class="wide">Endereço<input name="address" value="${esc(r.address||'')}"></label>`:''}</div></form>`,btn('Voltar','close')+btn('Salvar','simple-save',type+'|'+id,'primary'));}
function stockMove(id){const p=product(id);modal('Movimentação • '+esc(p.name),`<form id="stock-form"><p>Saldo atual: <b>${unit().stock[id]||0} ${esc(p.unit)}</b></p><div class="form-grid">${selectField('Tipo','type',[['retirada','Retirada / perda'],['entrada','Entrada / devolução'],['inventario','Inventário • saldo contado']],'retirada')}${field('Quantidade de embalagens/unidades','qty',1,'number','min="0" step="1" required')}<label class="wide">Motivo<input name="reason" required placeholder="Retirada da despensa, perda, contagem…"></label></div><div class="notice" style="margin-top:15px">Ajustes e perdas têm autorização apenas simulada. Sem autenticação nesta versão.</div></form>`,btn('Voltar','close')+btn('Confirmar movimento','stock-save',id,'primary'));}
function purchaseNew(id){const ps=state.products.filter(p=>['bebida','insumo'].includes(p.kind));modal('Solicitação de compra',`<p class="sub">Destino: estoque da filial selecionada. O time de compras definirá o fornecedor conforme as cotações.</p><form id="purchase-form"><div class="form-grid">${selectField('Produto','product',ps.map(p=>[p.id,p.name]),id||ps[0]?.id)}${field('Quantidade na unidade do estoque','qty',1,'number','min="1" step="1" required')}${field('Data necessária','date','','date','required')}<label class="wide">Justificativa<input name="reason" required></label></div></form>`,btn('Voltar','close')+btn('Criar solicitação','purchase-save','','primary'));}
function receivePurchase(id){const p=state.purchases.find(p=>p.id===id);modal('Conferir recebimento',`<form id="receive-form"><p><b>${esc(product(p.product).name)}</b> • faltam ${p.qty-(p.received||0)} unidades</p><div class="form-grid">${selectField('Filial destinatária','branch',state.branches.map(b=>[b.id,b.name]),branch)}${field('Chave / identificador da nota','note','','text','required')}${field('Embalagens recebidas','qty',1,'number','min="1" step="1" required')}${field('Unidades por embalagem','conversion',1,'number','min="1" step="1" required')}<label class="wide">Observação de divergência<input name="reason" placeholder="Opcional"></label></div><div class="notice" style="margin-top:15px">Somente a confirmação movimenta estoque. Para 1 caixa com 12 latas, informe 1 embalagem e conversão 12. Leitura de XML ainda não implementada.</div></form>`,btn('Voltar','close')+btn('Confirmar recebimento','receive-save',id,'primary'));}
function operationSettings(){const s=unit().settings;modal('Prazo e atendimento',`<form id="settings-form"><div class="form-grid">${field('Prazo da produção (minutos)','deadline',s.deadline,'number','min="1" max="240" required')}${field('Início do atendimento','opens',s.opens,'time','required')}${field('Fim do atendimento','closes',s.closes,'time','required')}</div><p class="sub">O horário limita a simulação de solicitação QR. Não há QR público nesta versão.</p></form>`,btn('Voltar','close')+btn('Salvar','settings-save','','primary'));}
function validForm(selector){const f=$(selector);if(!f.reportValidity())throw Error('Confira os campos obrigatórios.');return new FormData(f);}
function closeModal(){$('#modal').close();}
document.addEventListener('submit',e=>e.preventDefault());
