 if(a==='table-link'){const o=state.orders.find(o=>o.id===id);modal('Unir ou transferir mesas',`<form id="tables-form"><p>Comanda atual: <b>${locationLabel(o)}</b>. A primeira mesa selecionada será a principal.</p>${selectField('Operação','mode',[['unir','Unir às mesas atuais'],['transferir','Transferir para as selecionadas']],'unir')}<div class="check-list">${unit().tables.map(t=>{const other=tableOrder(t.id);return `<label><input type="checkbox" name="table" value="${t.id}">Mesa ${t.id} ${other&&other.id!==o.id?'• comanda #'+other.number:''}</label>`;}).join('')}</div><p class="sub">Ao unir mesas ocupadas, itens, pagamentos e descontos são preservados na comanda principal. Transferência só pode ser feita para mesas livres ou já vinculadas.</p></form>`,btn('Voltar','order-detail',id)+btn('Aplicar','tables-save',id,'primary'));return;}if(a==='tables-save'){const f=validForm('#tables-form'),selected=f.getAll('table').map(Number),o=state.orders.find(o=>o.id===id);if(!selected.length)throw Error('Selecione ao menos uma mesa.');if(f.get('mode')==='transferir'){if(selected.some(t=>{const other=tableOrder(t);return other&&other.id!==o.id;}))throw Error('Para transferir, selecione mesas livres. Use unir para combinar comandas.');o.tables=selected;}else{const others=[...new Set(selected.map(t=>tableOrder(t)).filter(other=>other&&other.id!==o.id))];if(others.some(other=>other.status!==o.status))throw Error('Confirme as solicitações pendentes antes de unir comandas.');others.forEach(other=>{o.created=Math.min(o.created,other.created);o.items.push(...other.items);o.payments.push(...other.payments);o.discount+=other.discount;o.people+=other.people;o.tables.push(...other.tables);other.items=[];other.payments=[];other.discount=0;other.fee=0;other.status='unificada';other.mergedInto=o.number;audit('Comanda unificada',`#${other.number} → #${o.number}`);});o.tables=[...new Set([...o.tables,...selected])];}audit('Mesas vinculadas',`#${o.number} • ${o.tables.join(' + ')}`);save('Mesas atualizadas.');orderDetail(id);return;}
